static int quadrat(int x) {
    return x * x;
}
static double quadrat(double x) {
    return x * x;
}
static boolean istGerade(int zahl) {
    return zahl % 2 == 0;
}
static int fakultaet(int n) {
    if (n <= 1) return 1;
    return n * fakultaet(n - 1);
}
static void gruesse(String name, int mal) {
    for (int i = 0; i < mal; i++) {
        System.out.println("Hallo " + name);
    }
}
static void verdopple(int[] a) {
    for (int i = 0; i < a.length; i++) a[i] *= 2;
}
static int zaehler = 0;
static void zaehle() { zaehler++; }
public static void main(String[] args) {
    System.out.println(quadrat(5));
    System.out.println(quadrat(1.5));
    System.out.println(istGerade(4) + " " + istGerade(7));
    System.out.println(fakultaet(10));
    gruesse("Java", 2);
    int[] z = {1, 2, 3};
    verdopple(z);
    System.out.println(Arrays.toString(z));
    zaehle(); zaehle();
    System.out.println(zaehler);
    System.out.println(fakultaet(13));
}
